package cn.bidcheck.verification;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class LayoutEvidenceIndexTest {
    Map<String,Object> cell(String id,String table,int row,int column,int block,String text){Map<String,Object> m=new LinkedHashMap<>();m.put("id",id);m.put("kind","TABLE_CELL");m.put("tableId",table);m.put("row",row);m.put("column",column);m.put("rowSpan",1);m.put("columnSpan",1);m.put("documentBlock",block);m.put("text",text);m.put("documentHash","a".repeat(64));m.put("documentVersion",2);m.put("source","OOXML_NATIVE");return m;}
    @Test void nativeWordHeaderSourcesRetainTheirOriginalBlocksAndVersion(){var header=cell("header","t",1,1,5,"姓名");var value=cell("value","t",3,1,7,"合成甲");var index=new LayoutEvidenceIndex();index.add("d",Map.of("status","COMPLETE","documentHash","a".repeat(64),"spans",List.of(header,value)));var out=index.apply(Map.of("documentId","d","location",7,"locationType","BLOCK"));assertEquals(2,out.size());assertEquals(Set.of(5,7),new HashSet<>(out.stream().map(r->r.get("location")).toList()));assertTrue(out.stream().allMatch(r->r.get("locationType").equals("BLOCK")&&r.get("documentVersion").equals(2)));assertTrue(out.stream().noneMatch(r->r.get("locationType").equals("PAGE")));}
    @Test void matchingNumberInDifferentLocationNamespaceDoesNotSelectAWordBlock(){var index=new LayoutEvidenceIndex();index.add("d",Map.of("status","COMPLETE","spans",List.of(cell("c","t",3,1,7,"甲"))));assertTrue(index.apply(Map.of("documentId","d","location",7,"locationType","PAGE")).isEmpty());}
    @Test void repeatedIdentifierRetrievesAdjacentHeaderAndDataButNeverSkippedPage(){var spans=new ArrayList<Map<String,Object>>();for(int page:List.of(1,2,4)){var id=cell("id"+page,"t"+page,3,2,page,"110101199001010011");id.put("physicalPage",page);var header=cell("header"+page,"t"+page,1,2,page,"身份证号码");header.put("physicalPage",page);spans.add(id);spans.add(header);}var index=new LayoutEvidenceIndex();index.add("d",Map.of("status","COMPLETE","spans",spans));var out=index.apply(Map.of("documentId","d","location",1,"locationType","PAGE"));assertEquals(Set.of(1,2),new HashSet<>(out.stream().map(r->r.get("location")).toList()));assertTrue(out.stream().anyMatch(r->r.get("spanId").equals("header2")));}
    @Test void eightyTextboxesAndEarlierRowsCannotStarveTheTargetRowAndRealHeaders(){var spans=new ArrayList<Map<String,Object>>();for(int i=0;i<100;i++)spans.add(new LinkedHashMap<>(Map.of("id","box"+i,"kind","OCR_TEXT_BOX","text","文字框"+i,"physicalPage",1)));for(int r=1;r<=100;r++)for(int c=1;c<=2;c++){var item=cell("row"+r+"col"+c,"large",r,c,1,r==1?(c==1?"姓名":"缴费月份"):r==99?(c==1?"目标甲":"2025-01、2025-02、2025-03"):"其他"+r+"值"+c);item.put("physicalPage",1);item.put("header",r==1);spans.add(item);}var index=new LayoutEvidenceIndex();index.add("d",Map.of("status","COMPLETE","spans",spans));var out=index.apply(Map.of("documentId","d","location",1,"locationType","PAGE","subject","目标甲"));var ids=out.stream().map(r->r.get("spanId")).toList();assertTrue(ids.containsAll(List.of("row99col1","row99col2","row1col1","row1col2")));assertTrue(out.size()<=120);assertTrue(out.stream().mapToInt(r->r.get("text").toString().length()).sum()<=16000);assertEquals("TABLE_CELL",out.get(0).get("kind"));}
    @Test void currentSourceQuoteCanSelectALateRowWithoutAResolvedPersonQuery(){var spans=new ArrayList<Map<String,Object>>();for(int r=1;r<=140;r++){var item=cell("r"+r,"t",r,1,1,r==1?"姓名":r==139?"目标甲":"其他人"+r);item.put("physicalPage",1);item.put("header",r==1);spans.add(item);}var index=new LayoutEvidenceIndex();index.add("d",Map.of("status","COMPLETE","spans",spans));var out=index.apply(Map.of("documentId","d","location",1,"locationType","PAGE","sourceQuote","姓名：目标甲 本月已缴纳"));assertTrue(out.stream().anyMatch(r->"r139".equals(r.get("spanId"))));}
}
